        /// <returns></returns>
        public static string[] BettransInsTransaction(int custId, DateTime transDate, double amount, string transDesc,
                                                      int userId, string lang, string ip)
        {
            string[] res = { "", "", "" };
            try
            {
                using (ObjectDb db = new ObjectDb("Acc_BettransInsTransaction", 300))
                {
                    var hash = new Hashtable();
                    hash.Add("transid", 0);
                    hash.Add("custid", custId);
                    hash.Add("transdate", transDate);
                    hash.Add("amount", amount);
                    hash.Add("transdesc", transDesc);
                    hash.Add("userid", userId);
                    hash.Add("errcode", 0);
                    hash.Add("errmsg", "");
                    hash.Add("language", lang);
                    hash.Add("ip", ip);

                    db.AssignParamValues(hash);
                    db.ExecuteNonQuery();

                    res[0] = string.Format("{0}", db.GetParameterValue("transid"));
                    res[1] = string.Format("{0}", db.GetParameterValue("errcode"));
                    res[2] = string.Format("{0}", db.GetParameterValue("errmsg"));
                }
            }
            catch (Exception ex)
            {
                Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
                res[0] = "0";
                res[1] = "100";
                res[2] = ex.Message;
            }
            return res;
        }

